Lemma bytes_le_to_Z_nonneg : forall bs, 0 <= bytes_le_to_Z bs.
Proof.
  induction bs as [|b bs IH]; cbn [bytes_le_to_Z]; [lia|].
  apply Z.lor_nonneg. split; [pose proof (bv_unsigned_in_range 8 b); lia | apply Z.shiftl_nonneg; exact IH].
Qed.

Lemma Z_to_le_bytes_to_Z : forall bs, Z_to_le_bytes (length bs) (bytes_le_to_Z bs) = bs.
Proof.
  induction bs as [|b bs IH]; [reflexivity|]. cbn [length Z_to_le_bytes bytes_le_to_Z].
  pose proof (bv_unsigned_in_range 8 b) as BR. unfold bv_modulus in BR. cbn in BR.
  pose proof (bytes_le_to_Z_nonneg bs) as NN.
  f_equal.
  - apply bv_eq. rewrite Z_to_bv_unsigned. unfold bv_wrap, bv_modulus. change (2 ^ Z.of_N 8) with (2^8).
    rewrite <- Z.land_ones by lia. rewrite Z.land_lor_distr_l.
    rewrite (Z.land_ones (bv_unsigned b) 8) by lia. rewrite Z.mod_small by lia.
    replace (Z.land (bytes_le_to_Z bs ≪ 8) (Z.ones 8)) with 0. { rewrite Z.lor_0_r. reflexivity. }
    symmetry. apply Z.bits_inj'. intros n Hn. rewrite Z.land_spec, Z.bits_0.
    destruct (Z.ltb_spec n 8).
    + rewrite Z.shiftl_spec_low by lia. reflexivity.
    + rewrite Z.ones_spec_high by lia. apply Bool.andb_false_r.
  - etransitivity; [| exact IH]. f_equal. rewrite Z.shiftr_lor, Z.shiftr_shiftl_l by lia. cbn [Z.sub].
    rewrite Z.shiftl_0_r. rewrite (Z.shiftr_div_pow2 (bv_unsigned b)) by lia. rewrite Z.div_small by (cbn; lia).
    rewrite Z.lor_0_l. reflexivity.
Qed.

Lemma bytes_le_to_Z_bound : forall bs, bytes_le_to_Z bs < 2 ^ (8 * Z.of_nat (length bs)).
Proof.
  intros bs. pose proof (bytes_le_to_Z_of_le_bytes (length bs) (bytes_le_to_Z bs) (bytes_le_to_Z_nonneg bs)) as E.
  rewrite Z_to_le_bytes_to_Z in E. rewrite E. apply Z.mod_pos_bound. lia.
Qed.

