Definition pf_L4_regs (rax spx gp tp t0 t1 t2 s0 s1 : word) (a0v a1v a2v : word) (a4 a6 a7 s2 s3 : word) (L : Z)
    (s5 s6 s7 s10 s11 t3 t4 t5 t6 : word) :=
  mkR rax spx gp tp t0 t1 t2 s0 s1 a0v a1v a2v (wz 31) a4 (wz 127) a6 a7 s2 s3 (wz L) s5 s6 s7 (wz 9) (wz 95) s10 s11 t3 t4 t5 t6.

(* [comment removed for export] *)
Local Ltac pf_L4_cont IH WIN LL L64 u L :=
  step;
  let KL := fresh "KL" in
  if_cases KL; zify_cond KL; rewrite ?unsigned_lit in KL by lia;
  [ apply evt_done; left; do 2 eexists; replace (u + 1) with L by lia; reflexivity
  | win_load (u + 1); step; step;
    replace (Z_to_bv 64 (u + 2)) with (Z_to_bv 64 (u + 1 + 1)) by (f_equal; lia);
    lazymatch goal with N' : nth_error _ (Z.to_nat (u + 1 - _)) = Some ?b' |- _ =>
      eapply evt_mono; [ eapply (IH (u + 1) (zb b')); [exact WIN | exact LL | exact L64 | lia | lia | exact N' | reflexivity] |];
      let ms := fresh "ms" in let PO := fresh "PO" in
      intros ms PO; cbv beta in PO; cbv beta;
      destruct PO as [A | [B | (u' & c' & b'' & a2' & EQ & R1 & R2 & R3 & R4 & R5)]];
      [ left; exact A | right; left; exact B | right; right; exists u', c', b'', a2'; repeat split; try fast_assumption; lia ]
    end ].
