Lemma pf_L4 : forall (k : nat) (u c : Z)
    rax spx gp tp t0 t1 t2 s0 s1 a2 a4 a6 a7 s2 s3 s5 s6 s7 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (p0 : Z) (bs : list byte) (L : Z) (bc : byte),
  bytes_at rsegs m1 p0 bs -> L = p0 + Z.of_nat (length bs) -> L < 2^64 -> p0 <= u < L -> (Z.to_nat (L - u) <= k)%nat ->
  nth_error bs (Z.to_nat (u - p0)) = Some bc -> zb bc = c ->
  evt rsegs (fun ms' =>
       (* [comment removed for export] *)
       (exists a1' a2', ms' = MS (pf_L4_regs rax spx gp tp t0 t1 t2 s0 s1 (wz L) a1' a2' a4 a6 a7 s2 s3 L s5 s6 s7 s10 s11 t3 t4 t5 t6)
                                F (Z_to_bv 64 0x3b180) fc None m1 (seg_rom rsegs))
    \/ (* [comment removed for export] *)
       (exists a0' a1' a2', ms' = MS (pf_L4_regs rax spx gp tp t0 t1 t2 s0 s1 a0' a1' a2' a4 a6 a7 s2 s3 L s5 s6 s7 s10 s11 t3 t4 t5 t6)
                                    F (Z_to_bv 64 0x3b2ec) fc None m1 (seg_rom rsegs))
    \/ (* [comment removed for export] *)
       (exists u' c' (b' : byte) a2', ms' = MS (pf_L4_regs rax spx gp tp t0 t1 t2 s0 s1 (wz (u' + 1)) (wz c') a2' a4 a6 a7 s2 s3 L s5 s6 s7 s10 s11 t3 t4 t5 t6)
                                       F (Z_to_bv 64 0x3b240) fc None m1 (seg_rom rsegs)
           /\ u <= u' < L /\ 0 <= c' < 32 /\ c' <> 9 /\ nth_error bs (Z.to_nat (u' - p0)) = Some b' /\ zb b' = c'))
    (MS (pf_L4_regs rax spx gp tp t0 t1 t2 s0 s1 (wz (u + 1)) (wz c) a2 a4 a6 a7 s2 s3 L s5 s6 s7 s10 s11 t3 t4 t5 t6)
