Lemma rw_cells_CB16_words : forall m A bs, rw_cells rsegs m A [CB 16 bs] ->
  rw_cells rsegs m A [C8 (le_bytes_to_word (firstn 8 bs)); C8 (le_bytes_to_word (skipn 8 bs))].
Proof.
  intros m A bs H. destruct (rw_cells_CB_split rsegs _ _ 16 8 _ H ltac:(lia)) as [H1 H2].
  apply rw_cells_CB8_C8 in H1. change (16 - 8)%nat with 8%nat in H2. apply rw_cells_CB8_C8 in H2.
  apply (proj2 (rw_cells_app rsegs m A [C8 (le_bytes_to_word (firstn 8 bs))] [C8 (le_bytes_to_word (skipn 8 bs))])).
  split; [exact H1 | cbn [cells_size csize Nat.add]; exact H2].
Qed.

