Lemma pf_ctx_fctx : forall m m1 sp sv E L lo p0 bs tl tmp pv nlen v1 v2 bsz bb e1 e2 e3 g,
  pf_ctx m m1 sp sv E L lo p0 bs (Z_to_bv 64 (bv_unsigned sp + 4152)) tl tmp pv (wz p0) (wz nlen) v1 v2 bsz bb e1 e2 e3 g ->
  pf_fctx m m1 sp sv E L lo p0 bs tl tmp pv nlen v1 v2 bsz bb e1 e2 e3 g.
Proof.
  intros until g. intros (SL & TL & TMP & FRhi & PPC & NMC & VLC & BFC & EC & WIN & LL & TB & HC & XS & ST & MU & WM & MI).
  apply (proj1 (rw_cells_app rsegs m1 (bv_unsigned sp + 48) [C8 (wz bsz)] [CB 4096 bb])) in BFC. destruct BFC as [BSZ BUF].
  cbn [cells_size csize Nat.add] in BUF. replace (bv_unsigned sp + 48 + Z.of_nat 8) with (bv_unsigned sp + 56) in BUF by lia.
  pose proof (rw_cells_CB_length _ _ _ _ BUF) as LBB. apply u8arr_of_rw_cells in BUF.
  unfold pf_fctx. repeat (split; [fast_assumption|]). fast_assumption.
Qed.

