(* [comment removed for export] *)
Definition pf_h36c_stmt (B : Z) : Prop :=
  forall (first cr : Z) rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 s11x
         s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (E L lo : Z) (p0 : Z) (bs : list byte) (E0 : ecv)
    (tl : list byte) (tmp : list cell) (pv nlen : Z) (v1 v2 : word) (bsz : Z) (bb : list byte) (g : bool),
  PF_L2_AT B ->
  pf_ctx m m1 sp (pf_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) E L lo p0 bs
         (Z_to_bv 64 (bv_unsigned sp + 4152)) tl tmp pv (wz p0) (wz nlen) v1 v2 bsz bb (wz (ec_val E0)) (wz (ec_cat E0)) (wz (ec_flags E0)) g ->
  pf_purei sp E lo p0 bs E0 -> 0 <= bsz <= 4096 -> cells_size tmp = 24%nat -> 0 <= pv < 2^64 ->
  1 <= nlen -> p0 + nlen < first -> first <= cr -> cr + 2 <= L -> L - (cr + 3) < B ->
  evt rsegs (pf_post ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc E lo p0 bs E0 m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -144)) gp tp t0 t1 t2 (wz E) (wz (cr + 2)) a0 a1 a2 a3 a4 a5 (wz 0x7c080) (wz 10)
              (Z_to_bv 64 (bv_unsigned sp + 48)) (Z_to_bv 64 (bv_unsigned sp + 40)) (wz L) (wz first) (wz first) (wz 32) (wz 9) (wz 95) (wz cr) s11x t3 t4 t5 t6)
        F (Z_to_bv 64 0x3b1d4) fc None m1 (seg_rom rsegs)).

