(* [comment removed for export] *)
Lemma pf_L3 : forall (B : Z) (k : nat) (q : Z) rax ra sp gp tp t0 t1 t2 a1 a2 a4 a5 s1x s10x s11x
         s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (E L lo : Z) (p0 : Z) (bs : list byte) (E0 : ecv)
    (sl : word) (tl : list byte) (tmp : list cell) (nlen : Z) (v1 v2 : word) (bsz : Z) (bb : list byte) (g : bool),
  PF_L2_AT B ->
  pf_ctx m m1 sp (pf_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) E L lo p0 bs
         sl tl tmp q (wz p0) (wz nlen) v1 v2 bsz bb (wz (ec_val E0)) (wz (ec_cat E0)) (wz (ec_flags E0)) g ->
  pf_purei sp E lo p0 bs E0 -> 0 <= bsz <= 4096 -> cells_size tmp = 24%nat ->
